16	    }
17	
18	    /**
19	     * The effective, business-day registration date: {@code supplied} when non-null, otherwise the
20	     * server's current date, rolled forward to the next Monday when it lands on a weekend.
21	     */
22	    static LocalDate effective(LocalDate supplied) {
23	        return toBusinessDay(supplied != null ? supplied : LocalDate.now());
24	    }
25	
26	    /** Roll a weekend date forward to the next Monday; a weekday is returned unchanged. */
27	    static LocalDate toBusinessDay(LocalDate date) {
28	        if (date.getDayOfWeek() == DayOfWeek.SATURDAY) {
29	            return date.plusDays(2);
30	        }
